package com.my-app.events.order_mgmt.order-line;

import java.util.LinkedHashMap;
import java.util.Map;

public record OrderLineItemAddedData(
    String sku,
    int qty,
    Double unitPrice
) {

    @SuppressWarnings("unchecked")
    public static OrderLineItemAddedData fromMap(Map<String, Object> map) {
        return new OrderLineItemAddedData(
            (String) map.get("sku"),
            (Integer) map.get("qty"),
            (Double) map.get("unitPrice")
        );
    }

    public Map<String, Object> toMap() {
        var map = new LinkedHashMap<String, Object>();
        map.put("sku", sku);
        map.put("qty", qty);
        map.put("unitPrice", unitPrice);
        return map;
    }
}

